import {
  Group, Mesh, Shape, ShapeGeometry, CircleGeometry, CylinderGeometry,
  MeshStandardNodeMaterial, MeshPhysicalNodeMaterial,
  Color, Vector2, Vector3, DirectionalLight, AmbientLight
} from 'three/webgpu';
import { uv, vec3, vec4, mix, uniform, time, add, mul, color } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  // Parse three card data groups
  const cardData = [];
  for (let i = 0; i < 3; i++) {
    const offset = i * 3;
    cardData.push({
      icon: items[offset]?.text ?? '',
      title: items[offset + 1]?.text ?? '',
      body: items[offset + 2]?.text ?? ''
    });
  }

  // Constants
  const cardW = 1.5;
  const cardH = 1.9;
  const cornerRadius = 0.06;
  const borderWidth = 0.006;
  const gap = 0.25;
  const totalWidth = cardW * 3 + gap * 2;
  const startX = -totalWidth / 2 + cardW / 2;

  // Shared materials for all cards (cloned later for per-card opacity)
  const borderColor = new Color('#26262f');
  const borderMat = new MeshStandardNodeMaterial({
    color: borderColor,
    roughness: 0.6,
    metalness: 0.25,
    clearcoat: 0.15,
    transparent: true,
    opacityNode: uniform(1)
  });

  // Disc cylinder geometry (0.4 diameter, extruded 0.05)
  const discGeo = new CylinderGeometry(0.2, 0.2, 0.05, 32);

  // Disc material with brushed anisotropy
  const discMat = new MeshPhysicalNodeMaterial({
    roughness: 0.55,
    metalness: 0.5,
    clearcoat: 0.2,
    anisotropy: 0.6,
    color: new Color('#191921'),
    transparent: true,
    opacityNode: uniform(1)
  });

  // Icon glyph material emissive
  const iconMat = new MeshPhysicalNodeMaterial({
    color: '#ff2a38',
    emissive: '#ff2a38',
    emissiveIntensity: 1.6,
    transparent: true,
    opacityNode: uniform(1)
  });

  // Contact shadow material
  const shadowOpacity = uniform(0.5);
  const shadowScale = uniform(1);
  const shadowGeo = new CircleGeometry(0.8, 32);
  const shadowMat = new MeshStandardNodeMaterial({
    color: new Color(0, 0, 0),
    transparent: true,
    opacityNode: shadowOpacity,
    roughness: 1,
    metalness: 0
  });

  // Helper: create a rounded rectangle shape
  function createRoundedRectShape(w, h, r) {
    const shape = new Shape();
    shape.moveTo(-w / 2 + r, -h / 2);
    shape.lineTo(w / 2 - r, -h / 2);
    shape.quadraticCurveTo(w / 2, -h / 2, w / 2, -h / 2 + r);
    shape.lineTo(w / 2, h / 2 - r);
    shape.quadraticCurveTo(w / 2, h / 2, w / 2 - r, h / 2);
    shape.lineTo(-w / 2 + r, h / 2);
    shape.quadraticCurveTo(-w / 2, h / 2, -w / 2, h / 2 - r);
    shape.lineTo(-w / 2, -h / 2 + r);
    shape.quadraticCurveTo(-w / 2, -h / 2, -w / 2 + r, -h / 2);
    return shape;
  }

  // Gradient material for card face
  const topColor = uniform(new Color('#191921'));
  const bottomColor = uniform(new Color('#121218'));
  const gradientNode = mix(topColor, bottomColor, uv().y);
  const cardMat = new MeshStandardNodeMaterial({
    roughness: 0.6,
    metalness: 0.25,
    clearcoat: 0.15,
    colorNode: gradientNode,
    transparent: true,
    opacityNode: uniform(1)
  });

  // Geometry for card border and face
  const borderShape = createRoundedRectShape(cardW + borderWidth * 2, cardH + borderWidth * 2, cornerRadius + borderWidth);
  const borderGeo = new ShapeGeometry(borderShape);
  const cardShape = createRoundedRectShape(cardW, cardH, cornerRadius);
  const cardGeo = new ShapeGeometry(cardShape);

  // Lights: add a key light (upper-left) and a rim light (lower-right)
  const keyLight = new DirectionalLight(0xffffff, 1.2);
  keyLight.position.set(1.5, 1.5, 3);
  keyLight.castShadow = false;

  const rimLight = new DirectionalLight(0xffffff, 0.6);
  rimLight.position.set(-1.5, -1.5, 2.5);

  // Create root group
  const root = new Group();
  root.add(keyLight);
  root.add(rimLight);

  // Store timelines and resources for cleanup
  const cleanupFns = [];
  const timelines = [];

  // Stagger entrance timeline (shared across cards)
  const entranceTL = gsap.timeline();

  // Pre-create all card groups and texts
  const cardGroups = [];

  cardData.forEach((data, index) => {
    const cardGroup = new Group();
    const xPos = startX + index * (cardW + gap);
    cardGroup.position.set(xPos, 0, 0);
    cardGroup.userData.isCard = true;

    // ----- Create a per-card opacity uniform -----
    const cardOpacity = uniform(0);
    // Assign to all child materials
    const matClone = (mat) => {
      const clone = mat.clone();
      clone.opacityNode = cardOpacity;
      clone.transparent = true;
      return clone;
    };

    // Border mesh
    const borderMesh = new Mesh(borderGeo, matClone(borderMat));
    borderMesh.position.z = -0.005;
    cardGroup.add(borderMesh);

    // Card face mesh
    const cardMesh = new Mesh(cardGeo, matClone(cardMat));
    cardGroup.add(cardMesh);

    // Contact shadow mesh (behind card)
    const shadowMesh = new Mesh(shadowGeo, shadowMat.clone());
    shadowMesh.position.z = -0.015;
    shadowMesh.scale.set(1, 1, 1);
    shadowMesh.material.opacityNode = shadowOpacity; // use shared uniform for hover effect
    cardGroup.add(shadowMesh);

    // Icon seat disc (cylinder)
    const disc = new Mesh(discGeo, matClone(discMat));
    // Position: interior padding 0.375 from top (card center y=0.95, top edge y=0.95, padding from top -> content area starts at y=0.95-0.375=0.575, disc center at half of diameter? We'll use y=0.5 as approximate)
    disc.position.set(0, 0.5, 0.01);
    cardGroup.add(disc);

    // Icon glyph
    const iconText = ctx.fontAtlas.createText(data.icon, {
      fontSize: 20,
      color: '#ff2a38',
      align: 'center'
    });
    // Replace material with iconMat
    iconText.traverse((child) => {
      if (child.isMesh) {
        child.material = matClone(iconMat);
      }
    });
    iconText.position.set(0, 0.5, 0.02);
    cardGroup.add(iconText);

    // Title text (using default white, but we want paper color)
    const titleText = ctx.fontAtlas.createText(data.title, {
      fontSize: 20,
      color: '#e8ecf2',
      align: 'center'
    });
    titleText.position.set(0, 0.0, 0.01); // gap 0.25 from icon? Actually spec: icon seat then 0.25 gap then title. So icon disc center at y=0.5, disc radius 0.2, so bottom of disc at y=0.3. Then gap 0.25, so title top at y=0.3-0.25=0.05? But 0.25 gap is from disc bottom to title top. Let's place title at y=0.0 (center of title line). Adjust accordingly.
    // Simpler: place title text at y = -0.1 (below disc) and body at y = -0.4
    cardGroup.add(titleText);

    // Body text
    const bodyText = ctx.fontAtlas.createText(data.body, {
      fontSize: 13,
      color: '#e8ecf2',
      align: 'center',
      maxWidthPx: 180
    });
    bodyText.position.set(0, -0.35, 0.01); // gap 0.125 from title? We'll approximate
    cardGroup.add(bodyText);

    // Store references for hover animation
    cardGroup.userData = {
      shadowMesh,
      iconText,
      disc,
      cardOpacity,
      cardMesh
    };

    // Hover handlers
    cardGroup.userData.handlers = {
      pointerenter: () => {
        // Kill any existing hover timeline for this card
        if (cardGroup.userData.hoverTL) {
          cardGroup.userData.hoverTL.kill();
        }
        const tl = gsap.timeline({ paused: true, overwrite: true });
        // Lift card position (y, z)
        tl.to(cardGroup.position, {
          y: 0.06,
          z: 0.12,
          duration: 0.18,
          ease: 'power2.out'
        }, 0);
        // Widen and soften shadow
        tl.to(shadowMesh.scale, {
          x: 1.3,
          y: 1.3,
          duration: 0.18,
          ease: 'power2.out'
        }, 0);
        tl.to(shadowOpacity, {
          value: 0.6,
          duration: 0.18,
          ease: 'power2.out'
        }, 0);
        // Increase icon emissive intensity
        const iconMatCloned = iconText.children[0]?.material;
        if (iconMatCloned) {
          tl.to(iconMatCloned, {
            emissiveIntensity: 2.2,
            duration: 0.18,
            ease: 'power2.out'
          }, 0);
        }
        tl.play();
        cardGroup.userData.hoverTL = tl;
        timelines.push(tl);
      },
      pointerleave: () => {
        if (cardGroup.userData.hoverTL) {
          cardGroup.userData.hoverTL.kill();
        }
        const tl = gsap.timeline({ paused: true, overwrite: true });
        tl.to(cardGroup.position, {
          y: 0,
          z: 0,
          duration: 0.18,
          ease: 'power2.out'
        }, 0);
        tl.to(shadowMesh.scale, {
          x: 1,
          y: 1,
          duration: 0.18,
          ease: 'power2.out'
        }, 0);
        tl.to(shadowOpacity, {
          value: 0.5,
          duration: 0.18,
          ease: 'power2.out'
        }, 0);
        const iconMatCloned = iconText.children[0]?.material;
        if (iconMatCloned) {
          tl.to(iconMatCloned, {
            emissiveIntensity: 1.6,
            duration: 0.18,
            ease: 'power2.out'
          }, 0);
        }
        tl.play();
        cardGroup.userData.hoverTL = tl;
        timelines.push(tl);
      }
    };

    // Add entrance animation: fade-up and opacity
    entranceTL.to(cardOpacity, {
      value: 1,
      duration: 0.5,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
    }, index * 0.08);
    entranceTL.fromTo(cardGroup.position, {
      y: cardGroup.position.y + 0.2
    }, {
      y: cardGroup.position.y,
      duration: 0.5,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
    }, index * 0.08);

    cardGroups.push(cardGroup);
    root.add(cardGroup);
  });

  timelines.push(entranceTL);

  // Set root event handlers (empty, but required)
  root.userData.handlers = {};

  // Cleanup function
  root.userData.cleanup = () => {
    timelines.forEach(tl => tl.kill());
    // Dispose materials, geometries, and children
    root.traverse((child) => {
      if (child.isMesh) {
        if (child.geometry) child.geometry.dispose();
        if (child.material) {
          if (Array.isArray(child.material)) {
            child.material.forEach(m => m.dispose());
          } else {
            child.material.dispose();
          }
        }
      }
    });
    // Remove all children
    while (root.children.length) {
      root.remove(root.children[0]);
    }
  };

  return root;
}
